      // Hanya TIGA baris keadaan. Sisanya (zona, momentum, volume) sudah terjawab oleh Key
      // Levels dan Current Reading di bawahnya — mengulanginya sebagai baris label/nilai
      // membuat konsol panjang tanpa menambah jawaban.
      rows: [
        ['Primary Trend', R.trenPrimer],
        ['Current State', R.negara],
        ['Market Bias', R.bias],
      ],
      berikut: R.berikut,
      bacaan: A.bacaan || [],
      tangga: A.tangga || [],
      skenario: (A.skenario || []).map(s => ({ tahap: s.tahap, nama: s.nama, jika: s.jika, maka: s.maka, kelas: s.kelas })),
      kesimpulan: A.kesimpulan,
